class Solution {
public:
    int numPermsDISequence(string s) {
        const long long MOD = 1000000007;
        int n = s.size();
        vector<long long> dp(n + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            vector<long long> pref(i + 1, 0);
            for (int j = 0; j < i; j++) pref[j + 1] = (pref[j] + dp[j]) % MOD;
            vector<long long> ndp(n + 1, 0);
            char c = s[i - 1];
            for (int j = 0; j <= i; j++) {
                if (c == 'I') {
                    ndp[j] = pref[j];
                } else {
                    ndp[j] = (pref[i] - pref[j] + MOD) % MOD;
                }
            }
            dp = ndp;
        }
        long long ans = 0;
        for (int j = 0; j <= n; j++) ans = (ans + dp[j]) % MOD;
        return (int)ans;
    }
};
